package com.rustyledger.repository;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;

public class ReportRepository {
    private final Map<String, int[]> counts = new HashMap<>();
    private final Map<String, Map<String, BigDecimal>> fees = new HashMap<>();

    public void increment(String date, int isRejected) {
        int[] c = counts.computeIfAbsent(date, k -> new int[2]);
        c[isRejected]++;
    }

    public void addFee(String date, String currency, BigDecimal delta) {
        if (delta.signum() == 0) return;
        Map<String, BigDecimal> m = fees.computeIfAbsent(date, k -> new TreeMap<>());
        m.put(currency, m.getOrDefault(currency, BigDecimal.ZERO).add(delta));
    }

    public int getCount(String date, int isRejected) {
        int[] c = counts.get(date);
        return c == null ? 0 : c[isRejected];
    }

    public Map<String, BigDecimal> getFees(String date) {
        return fees.getOrDefault(date, new TreeMap<>());
    }
}

package com.rustyledger.service;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class FeeCalculator {
    public BigDecimal calculateTransferFee(String tier, BigDecimal amount) {
        if ("STANDARD".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.005")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.20"));
        }
        if ("PREMIUM".equals(tier)) {
            BigDecimal fee = amount.multiply(new BigDecimal("0.0025")).setScale(2, RoundingMode.HALF_UP);
            return fee.max(new BigDecimal("0.10")).min(new BigDecimal("5.00"));
        }
        return BigDecimal.ZERO;
    }

    public BigDecimal calculateWithdrawalFee(String tier) {
        return "STANDARD".equals(tier) ? new BigDecimal("1.00") : BigDecimal.ZERO;
    }
}

package com.rustyledger.service;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class CurrencyConverter {
    private BigDecimal rate(String currency) {
        if ("EUR".equals(currency)) return new BigDecimal("4.30");
        if ("USD".equals(currency)) return new BigDecimal("4.00");
        return BigDecimal.ONE;
    }

    public BigDecimal convert(BigDecimal amount, String from, String to, String tier) {
        BigDecimal inPln = amount.multiply(rate(from)).setScale(4, RoundingMode.HALF_UP);
        BigDecimal result = inPln.divide(rate(to), 4, RoundingMode.HALF_UP);
        if (!"STAFF".equals(tier)) {
            result = result.multiply(new BigDecimal("0.985"));
        }
        return result.setScale(2, RoundingMode.HALF_DOWN);
    }
}

package com.rustyledger.service;

import com.rustyledger.model.Account;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;

public class LimitChecker {
    private final Map<String, BigDecimal> usedToday = new HashMap<>();

    public String check(String id, String date, Account a, BigDecimal amount, BigDecimal fee) {
        String tier = a.tier;
        BigDecimal limit = getLimit(tier);
        BigDecimal overdraft = getOverdraft(tier);
        BigDecimal currentUsed = usedToday.getOrDefault(id + "|" + date, BigDecimal.ZERO);

        if (currentUsed.add(amount).compareTo(limit) > 0) {
            return "LIMIT_EXCEEDED: daily limit " + limit + " for " + tier;
        }
        BigDecimal needed = amount.add(fee);
        if (a.balance.subtract(needed).compareTo(overdraft.negate()) < 0) {
            return "INSUFFICIENT_FUNDS: balance " + a.balance + " " + a.currency + 
                   ", needed " + needed + " " + a.currency;
        }
        return null;
    }

    private BigDecimal getLimit(String tier) {
        if ("STANDARD".equals(tier)) return new BigDecimal("5000.00");
        if ("PREMIUM".equals(tier)) return new BigDecimal("20000.00");
        return new BigDecimal("50000.00");
    }

    private BigDecimal getOverdraft(String tier) {
        return "PREMIUM".equals(tier) ? new BigDecimal("500.00") : BigDecimal.ZERO;
    }

    public void addUsed(String id, String date, BigDecimal amount) {
        String key = id + "|" + date;
        usedToday.put(key, usedToday.getOrDefault(key, BigDecimal.ZERO).add(amount));
    }
}

package com.rustyledger;

import com.rustyledger.model.*;
import com.rustyledger.repository.*;
import com.rustyledger.service.*;
import java.math.BigDecimal;
import java.util.*;

public class LedgerImpl implements Ledger {
    private final AccountRepository accounts = new AccountRepository();
    private final TransactionRepository txs = new TransactionRepository();
    private final AuditRepository audit = new AuditRepository();
    private final ReportRepository reports = new ReportRepository();
    private final FeeCalculator feeCalc = new FeeCalculator();
    private final CurrencyConverter converter = new CurrencyConverter();
    private final LimitChecker limits = new LimitChecker();

    public void openAccount(String id, String tier, String currency, String balance) {
        validateAccount(id, tier, currency, balance);
        accounts.add(id, new Account(tier, currency, new BigDecimal(balance).setScale(2)));
    }

    private void validateAccount(String id, String tier, String currency, String balance) {
        if (id == null || id.trim().isEmpty() || id.contains("|")) 
            throw new IllegalArgumentException("INVALID ACCOUNT ID");
        if (!Set.of("STANDARD", "PREMIUM", "STAFF").contains(tier)) 
            throw new IllegalArgumentException("INVALID TIER: " + tier);
        if (!Set.of("PLN", "EUR", "USD").contains(currency)) 
            throw new IllegalArgumentException("INVALID CURRENCY: " + currency);
        if (balance == null || !balance.matches("\\d+(\\.\\d{1,2})?")) 
            throw new IllegalArgumentException("INVALID AMOUNT: " + balance);
        if (accounts.exists(id)) throw new IllegalStateException("ACCOUNT EXISTS: " + id);
    }

    public String balance(String id) {
        Account a = accounts.get(id);
        if (a == null) throw new IllegalArgumentException("UNKNOWN ACCOUNT: " + id);
        return a.balance.setScale(2, BigDecimal.ROUND_HALF_UP).toString() + " " + a.currency;
    }

    public List<String> auditLog() { return audit.getLog(); }

    public String dailyReport(String date) {
        int ok = reports.getCount(date, 0);
        int rejected = reports.getCount(date, 1);
        Map<String, BigDecimal> f = reports.getFees(date);
        String feeText = "none";
        if (!f.isEmpty()) {
            List<String> parts = new ArrayList<>();
            f.forEach((cur, val) -> parts.add(val.setScale(2, BigDecimal.ROUND_HALF_UP).toString() + " " + cur));
            feeText = String.join(", ", parts);
        }
        return "REPORT " + date + "\nok: " + ok + "\nrejected: " + rejected + "\nfees: " + feeText;
    }

    public String submit(String line) {
        if (line == null || line.trim().isEmpty()) 
            return reject("???", null, "BAD_INSTRUCTION", "empty instruction");
        String[] f = line.split("\\|", -1);
        String verb = f[0];
        int want = getWant(verb);
        if (want == -1) return reject("???", null, "BAD_INSTRUCTION", "unknown verb " + verb);
        if (f.length != want) return reject(verb, null, "BAD_INSTRUCTION", verb + " needs " + want + " fields");
        String date = f[1];
        if (!date.matches("\\d{4}-\\d{2}-\\d{2}")) return reject(verb, null, "BAD_DATE", date);
        if (verb.equals("REVERSE")) return doReverse(date, f[2]);
        String amtStr = verb.equals("TRANSFER") ? f[4] : f[3];
        if (!amtStr.matches("\\d+(\\.\\d{1,2})?")) return reject(verb, date, "BAD_AMOUNT", amtStr);
        BigDecimal amount = new BigDecimal(amtStr).setScale(2, BigDecimal.ROUND_HALF_UP);
        if (amount.signum() <= 0) return reject(verb, date, "BAD_AMOUNT", amtStr);
        if (verb.equals("TRANSFER")) return doTransfer(date, f[2], f[3], amount, f[5]);
        if (verb.equals("WITHDRAW")) return doWithdraw(date, f[2], amount);
        return doDeposit(date, f[2], amount);
    }

    private int getWant(String verb) {
        if (verb.equals("TRANSFER")) return 6;
        if (verb.equals("WITHDRAW") || verb.equals("DEPOSIT")) return 4;
        if (verb.equals("REVERSE")) return 3;
        return -1;
    }

    private String doTransfer(String date, String fromId, String toId, BigDecimal amount, String cur) {
        Account from = accounts.get(fromId);
        Account to = accounts.get(toId);
        if (from == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", fromId);
        if (to == null) return reject("TRANSFER", date, "UNKNOWN_ACCOUNT", toId);
        if (fromId.equals(toId)) return reject("TRANSFER", date, "SAME_ACCOUNT", "cannot transfer to the same account");
        if (!from.currency.equals(cur)) return reject("TRANSFER", date, "CURRENCY_MISMATCH", fromId + " holds " + from.currency);
        BigDecimal fee = feeCalc.calculateTransferFee(from.tier, amount);
        String limitErr = limits.check(fromId, date, from, amount, fee);
        if (limitErr != null) return rejectTransferErr(date, limitErr);
        BigDecimal credited = from.currency.equals(to.currency) ? amount : converter.convert(amount, from.currency, to.currency, from.tier);
        from.balance = from.balance.subtract(amount.add(fee));
        to.balance = to.balance.add(credited);
        limits.addUsed(fromId, date, amount);
        String tid = txs.nextId();
        txs.put(tid, new Transaction("TRANSFER", date, fromId, toId, amount, from.currency, fee, credited));
        reports.increment(date, 0);
        reports.addFee(date, from.currency, fee);
        return accept("TRANSFER", date, tid, "fee=" + fee.setScale(2, BigDecimal.ROUND_HALF_UP) + " " + from.currency);
    }

    private String rejectTransferErr(String date, String err) {
        String code = err.substring(0, err.indexOf(':')).trim();
        String msg = err.substring(err.indexOf(':') + 1).trim();
        return reject("TRANSFER", date, code, msg);
    }

    private String doWithdraw(String date, String id, BigDecimal amount) {
        Account a = accounts.get(id);
        if (a == null) return reject("WITHDRAW", date, "UNKNOWN_ACCOUNT", id);
        BigDecimal fee = feeCalc.calculateWithdrawalFee(a.tier);
        String limitErr = limits.check(id, date, a, amount, fee);
        if (limitErr != null) return rejectWithdrawErr(date, limitErr);
        a.balance = a.balance.subtract(amount.add(fee));
        limits.addUsed(id, date, amount);
        String tid = txs.nextId();
        txs.put(tid, new Transaction("WITHDRAW", date, id, "", amount, a.currency, fee, amount));
        reports.increment(date, 0);
        reports.addFee(date, a.currency, fee);
        return accept("WITHDRAW", date, tid, "fee=" + fee.setScale(2, BigDecimal.ROUND_HALF_UP) + " " + a.currency);
    }

    private String rejectWithdrawErr(String date, String err) {
        String code = err.substring(0, err.indexOf(':')).trim();
        String msg = err.substring(err.indexOf(':') + 1).trim();
        return reject("WITHDRAW", date, code, msg);
    }

    private String doDeposit(String date, String id, BigDecimal amount) {
        Account a = accounts.get(id);
        if (a == null) return reject("DEPOSIT", date, "UNKNOWN_ACCOUNT", id);
        a.balance = a.balance.add(amount);
        String tid = txs.nextId();
        txs.put(tid, new Transaction("DEPOSIT", date, id, "", amount, a.currency, BigDecimal.ZERO, amount));
        reports.increment(date, 0);
        return accept("DEPOSIT", date, tid, "fee=0.00 " + a.currency);
    }

    private String doReverse(String date, String tid) {
        Transaction tx = txs.get(tid);
        if (tx == null) return reject("REVERSE", date, "UNKNOWN_TX", tid);
        if (!tx.verb.equals("TRANSFER")) return reject("REVERSE", date, "NOT_REVERSIBLE", tid + " is a " + tx.verb);
        if (tx.reversed) return reject("REVERSE", date, "ALREADY_REVERSED", tid);
        if (!tx.date.equals(date)) return reject("REVERSE", date, "REVERSAL_WINDOW", tid + " was made on " + tx.date);
        Account from = accounts.get(tx.fromId);
        Account to = accounts.get(tx.toId);
        to.balance = to.balance.subtract(tx.credited);
        BigDecimal back = tx.amount;
        if ("PREMIUM".equals(from.tier)) {
            back = back.add(tx.fee);
            if (tx.fee.signum() != 0) reports.addFee(date, from.currency, tx.fee.negate());
        }
        from.balance = from.balance.add(back);
        tx.reversed = true;
        String newTid = txs.nextId();
        txs.put(newTid, new Transaction("REVERSE", date, tx.fromId, tx.toId, tx.amount, tx.currency, BigDecimal.ZERO, tx.credited));
        reports.increment(date, 0);
        return accept("REVERSE", date, newTid, "reversed " + tid);
    }

    private String accept(String verb, String date, String tid, String extra) {
        reports.increment(date, 0);
        audit.record(verb, date, "OK " + tid);
        return "OK " + tid + " " + extra;
    }

    private String reject(String verb, String date, String code, String msg) {
        if (date != null) reports.increment(date, 1);
        audit.record(verb, date == null ? "????-??-??" : date, "REJECTED " + code);
        return "REJECTED " + code + ": " + msg;
    }
}

